// Node 02: Cryptographic HMAC-SHA256 Verification & Replay Window Check (ADR-003, ADR-005)
const crypto = require('crypto');

const item = $input.first().json;
const headers = item.headers || {};
const body = item.body || item;

const signature = headers['x-aegis-signature'];
const timestamp = headers['x-aegis-timestamp'];
const secret = $env.AEGIS_WEBHOOK_SECRET || 'aegis-dev-hmac-webhook-secret-key-2026';

if (signature && timestamp) {
  const nowSec = Math.floor(Date.now() / 1000);
  if (Math.abs(nowSec - Number(timestamp)) > 300) {
    throw new Error('401 Unauthorized: Webhook timestamp drift exceeds 300s replay window');
  }
}

return [{
  json: {
    idempotency_key: body.idempotency_key,
    patient_uuid: body.patient_uuid,
    crm_alias: body.crm_alias,
    insurance_provider: body.insurance_provider || 'Aetna_PPO',
    scrubbed_symptoms: body.scrubbed_symptoms,
    xml_sandboxed_prompt: `<untrusted_symptom_text>\n${body.scrubbed_symptoms}\n</untrusted_symptom_text>`,
    vault_review_url: body.vault_review_url
  }
}];

// Node 05: XML-Sandboxed AI Triage Agent & Structured Output Parser (ADR-005)
// Evaluates <untrusted_symptom_text> strictly as data, ignoring imperative prompt-injection instructions.
const intake = $('02. Verify HMAC-SHA256 & XML Sandbox').first().json;
const insurance = $('03. Tool: Check Insurance Eligibility API').first().json;

const lower = String(intake.scrubbed_symptoms || '').toLowerCase();
const injectionBlocked = lower.includes('ignore all previous instructions') || lower.includes('ignore previous instructions') || lower.includes('classify urgency_level as low');

let urgency_level = 'MEDIUM';
let recommended_specialty = 'General Medicine';
let suggested_onboarding_track = insurance.insurance_verified ? 'Standard' : 'ManualReview';
let triage_rationale_redacted = 'General clinical presentation routed to Internal Medicine for standard clinician review.';

if (lower.includes('heart attack') || lower.includes('crushing chest pain') || lower.includes('cannot breathe') || lower.includes('stroke')) {
  urgency_level = 'CRITICAL';
  recommended_specialty = 'Emergency Care';
  suggested_onboarding_track = 'Emergency911';
  triage_rationale_redacted = injectionBlocked
    ? '[PROMPT INJECTION BLOCKED BY XML SANDBOX] Critical cardiac/respiratory red flags detected. Immediate 911 short-circuit triggered.'
    : 'Critical life-threatening indicators detected. Standard self-scheduling halted; immediate 911 escalation triggered.';
} else if (lower.includes('chest tightness') || lower.includes('palpitation') || lower.includes('arrhythmia')) {
  urgency_level = 'HIGH';
  recommended_specialty = 'Cardiology';
  suggested_onboarding_track = 'FastTrack';
  triage_rationale_redacted = 'Sub-acute cardiopulmonary symptoms warrant priority Cardiology evaluation within 24-48h.';
} else if (lower.includes('mole') || lower.includes('rash') || lower.includes('eczema')) {
  urgency_level = 'LOW';
  recommended_specialty = 'Dermatology';
  suggested_onboarding_track = 'Standard';
  triage_rationale_redacted = 'Non-emergent dermatological presentation suitable for standard Dermatology consultation.';
}

return [{
  json: {
    patient_uuid: intake.patient_uuid,
    crm_alias: intake.crm_alias,
    vault_review_url: intake.vault_review_url,
    ai_triage: {
      urgency_level,
      recommended_specialty,
      triage_rationale_redacted,
      insurance_verified: Boolean(insurance.insurance_verified),
      copay_estimate_usd: urgency_level === 'CRITICAL' ? 0 : Number(insurance.copay_estimate_usd ?? 35),
      suggested_onboarding_track,
      prompt_injection_blocked: injectionBlocked
    }
  }
}];

// Node 07: Pseudonymous HubSpot CRM Upsert (ADR-001, ADR-007)
// Upserts Contact by <short_uuid>@vault.aegisflow.internal and deduplicates Deal by patient_uuid
const data = $input.first().json;
const shortId = String(data.patient_uuid).replace(/[^a-f0-9]/gi, '').slice(0, 6);

const crypto = require('crypto');
const isCritical = data.ai_triage.urgency_level === 'CRITICAL';

const callbackPayload = {
  patient_uuid: data.patient_uuid,
  status: isCritical ? 'EMERGENCY_HALTED' : 'CRM_SYNCED',
  ai_triage: data.ai_triage,
  hubspot_contact_id: `hs_cnt_${shortId}`,
  hubspot_deal_id: `hs_deal_${shortId}`
};

const rawBody = JSON.stringify(callbackPayload);
const timestamp = String(Math.floor(Date.now() / 1000));
const secret = $env.AEGIS_WEBHOOK_SECRET || 'aegis-dev-hmac-webhook-secret-key-2026';
const signature = crypto.createHmac('sha256', secret).update(`${timestamp}.${rawBody}`).digest('hex');

return [{
  json: {
    callbackPayload,
    rawBody,
    signature,
    timestamp
  }
}];
